				return TowerActiveStardust;

			return false;
		}
	}

	/// <summary>
	/// The transparency of the NPC expressed as a float value from 0f (transparent) to 1f (opaque). This property wraps <see cref="alpha"/>.
	/// </summary>
	public float Opacity {
		get {
			return 1f - (float)alpha / 255f;
		}
		set {
			alpha = (int)MathHelper.Clamp((1f - value) * 255f, 0f, 255f);
		}
	}

	public bool TreatedAsABossForRainbowBoulders {
		get {
			if (!boss)
