	/// Returns true if either <see cref="NPCID.Sets.ActsLikeTownNPC"/> or <see cref="townNPC"/> is true.
	/// </summary>
	public bool isLikeATownNPC {
		get {
			if (NPCID.Sets.ActsLikeTownNPC[type])
				return true;

			return townNPC;
		}
	}

	public static bool IsMechQueenUp {
		get {
			if (mechQueen >= 0 && mechQueen < Main.maxNPCs) {
				if (Main.npc[mechQueen].active && Main.npc[mechQueen].type == 127)
					return true;

				mechQueen = -1;
				return false;
			}

			return false;
		}
	}

