	/// <summary>
	/// Returns the <see cref="FullName"/> of the first active NPC of the given type in the world. If not found, the type name is returned instead.
	/// </summary>
	/// <param name="npcID"></param>
	/// <returns></returns>
	public static string GetFullnameByID(int npcID)
	{
		for (int i = 0; i < Main.maxNPCs; i++) {
			if (Main.npc[i].active && Main.npc[i].type == npcID)
				return Main.npc[i].FullName;
		}

		return Lang.GetNPCNameValue(npcID);
	}

	public static bool BusyWithAnyInvasionOfSorts()
	{
		if (Main.slimeRainTime == 0.0 && !Main.bloodMoon && !Main.eclipse && !Main.snowMoon && !Main.pumpkinMoon && Main.invasionType == 0)
			return DD2Event.Ongoing;

		return true;
	}

	public float GetKnockbackMultiplier_ScaledByDifficulty(float normalKnockbackMult) => normalKnockbackMult * GameDifficultyData.KnockbackToEnemiesMultiplier.Sample(difficulty);
	public int GetAttackDamage_ScaledByDifficulty(float normalDamage) => (int)(normalDamage * GameDifficultyData.EnemyDamageMultiplier.Sample(difficulty));

	public int GetAttackDamage_CappedAtMaster(float normalDamage)
	{
		float num = Math.Min(difficulty, GameDifficultyLevel.Master);
		return (int)(normalDamage * GameDifficultyData.EnemyDamageMultiplier.Sample(num));
	}

	public int GetAttackDamage_LerpBetweenFinalValues(float normalDamage, float expertDamage) => (int)Utils.Remap(difficulty, GameDifficultyLevel.Classic, GameDifficultyLevel.Expert, normalDamage, expertDamage);
	public int GetAttackDamage_ForProjectiles(float normalDamage, float expertDamage) => (int)Utils.Remap(difficulty, GameDifficultyLevel.Classic, GameDifficultyLevel.Expert, normalDamage, expertDamage);
	public int GetAttackDamage_ForProjectiles_MultiLerp(float normalDamage, float expertDamage, float masterDamage) => (int)Utils.MultiLerp(Utils.GetLerpValue(GameDifficultyLevel.Classic, GameDifficultyLevel.Master, difficulty, clamped: true), normalDamage, expertDamage, masterDamage);
	public int GetAttackDamage_ForTownNPC(float normalDamage) => (int)(normalDamage * GameDifficultyData.TownNPCDamageMultiplier.Sample(Main.Difficulty));

	public static bool SpawnAllowed_Demolitionist()
	{
		if (unlockedDemolitionistSpawn)
			return true;

		for (int i = 0; i < 255; i++) {
			Player player = Main.player[i];
			if (!player.active)
				continue;

			for (int j = 0; j < 58; j++) {
				Item item = player.inventory[j];
				if (item != null && item.stack > 0 && ItemID.Sets.ItemsThatCountAsBombsForDemolitionistToSpawn[item.type])
					return true;
			}
		}

		return false;
	}

	public static bool SpawnAllowed_ArmsDealer()
	{
		if (unlockedArmsDealerSpawn)
			return true;

		for (int i = 0; i < 255; i++) {
			Player player = Main.player[i];
			if (!player.active)
				continue;

			for (int j = 0; j < 58; j++) {
				Item item = player.inventory[j];
				if (item != null && item.stack > 0 && (item.ammo == AmmoID.Bullet || item.useAmmo == AmmoID.Bullet))
					return true;
			}
		}

		return false;
	}

	public static bool SpawnAllowed_DyeTrader()
	{
		if (unlockedDyeTraderSpawn)
			return true;

		for (int i = 0; i < 255; i++) {
			Player player = Main.player[i];
			if (!player.active)
				continue;

			for (int j = 0; j < 58; j++) {
				Item item = player.inventory[j];
				if (item != null && item.stack > 0 && (item.dye > 0 || (item.type >= 1107 && item.type <= 1120) || (item.type >= 3385 && item.type <= 3388)))
					return true;
			}

			for (int k = 0; k < 10; k++) {
				Item item2 = player.dye[k];
				if (item2 != null && item2.stack > 0 && item2.dye > 0)
					return true;
			}

			for (int l = 0; l < 5; l++) {
				Item item3 = player.miscDyes[l];
				if (item3 != null && item3.stack > 0 && item3.dye > 0)
					return true;
			}
		}

		return false;
	}

	public static bool SpawnAllowed_Nurse()
	{
		if (unlockedNurseSpawn)
			return true;

		for (int i = 0; i < 255; i++) {
			Player player = Main.player[i];
			/*
			if (player.active && player.statLifeMax / 20 > 5)
			*/
			if (player.active && player.ConsumedLifeCrystals > 0)
				return true;
		}

		return false;
	}

	public static bool SpawnAllowed_Merchant()
	{
		if (unlockedMerchantSpawn)
			return true;

		double num = 5000.0;
		int num2 = 0;
		for (int i = 0; i < 255; i++) {
			Player player = Main.player[i];
			if (!player.active)
				continue;

			for (int j = 0; j < 58; j++) {
				Item item = player.inventory[j];
				if (item != null && item.stack > 0) {
					if (item.type == 71)
						num2 += item.stack;

					if (item.type == 72)
						num2 += item.stack * 100;

					if (item.type == 73)
						num2 += item.stack * 10000;

					if (item.type == 74)
						num2 += item.stack * 1000000;

					if ((double)num2 >= num)
						return true;
				}
			}
		}

		return false;
	}

	public static void ClearFoundActiveNPCs()
	{
		for (int i = 0; i < npcsFoundForCheckActive.Length; i++) {
			npcsFoundForCheckActive[i] = false;
		}
	}

	public static void UpdateFoundActiveNPCs()
	{
		for (int i = 0; i < Main.maxNPCs; i++) {
			NPC nPC = Main.npc[i];
			if (nPC.active && nPC.type >= 0)
				npcsFoundForCheckActive[nPC.type] = true;
		}
	}

	public static void ClearFoundNPCTypesForBestiary()
	{
		for (int i = 0; i < npcsFoundForCheckActive.Length; i++) {
			npcsFoundForCheckActive[i] = false;
		}
	}

	public void EncourageDespawn(int despawnTime)
	{
		if (timeLeft > despawnTime)
			timeLeft = despawnTime;

		despawnEncouraged = true;
	}

	public void DiscourageDespawn(int despawnTime)
	{
		if (timeLeft < despawnTime)
			timeLeft = despawnTime;

		despawnEncouraged = false;
	}

	public static bool WouldBeEncouragedToDespawn(int aistyle, int type)
	{
		if (aistyle == 4)
			return Main.dayTime;

		return false;
	}

	/*
	public static string getNewNPCName(int npcType) => getNewNPCNameInner(npcType);
	*/
	public string getNewNPCName()
	{
		string npcNameCategoryKey = getNewNPCNameInner(type);
		var npcNameList = new List<string>();

		if (!string.IsNullOrEmpty(npcNameCategoryKey))
			npcNameList = LanguageManager.Instance.GetLocalizedEntriesInCategory(npcNameCategoryKey);

		npcNameList = NPCLoader.ModifyNPCNameList(this, npcNameList);

		if (npcNameList != null && npcNameList.Count > 0)
			return npcNameList[WorldGen.genRand.Next(npcNameList.Count)];
		else
			return "";
	}

	//TML: A dummy for tricking 'getNewNPCNameInner' into returning category names.
	private readonly ref struct NPCNameFakeLanguageCategoryPassthrough
	{
		public struct V { public string Value; }
		public readonly V RandomFromCategory(string category, UnifiedRandom _) => new V { Value = category };
	}

	private static string getNewNPCNameInner(int npcType)
	{
		// Delightfully devilish.
		var Language = new NPCNameFakeLanguageCategoryPassthrough();

		switch (npcType) {
