	private void getZenithSeedAdjustmentsBeforeEverything()
	{
		int num = type;
		if ((uint)(num - 125) <= 6u || num == 139)
			lifeMax = (int)((float)lifeMax * 0.8f);
	}

	private void getGoodAdjustments()
	{
		float num = scale;
		if (type == 13) {
			scale *= 1.35f;
			defense += 2;
		}
		else if (type == 14) {
			scale *= 1.4f;
			defense += 2;
		}
		else if (type == 15) {
			scale *= 1.4f;
			defense += 2;
		}
		else if (type == 40 || type == 39 || type == 41) {
			lifeMax += 100;
			defense += 2;
			damage += 4;
			scale = 1.1f;
			if (Main.remixWorld) {
				lifeMax += 50;
				scale *= 1.2f;
				defense += 4;
			}
		}
		else if (type == 35) {
			scale *= 1.25f;
		}
		else if (type == 36) {
			scale *= 1.15f;
		}
		else if (type == 113) {
			scale *= 0.65f;
			lifeMax = (int)((double)lifeMax * 1.5);
			defense += 3;
		}
		else if (type == 114) {
			scale *= 0.65f;
			lifeMax = (int)((double)lifeMax * 1.5);
			defense += 3;
		}
		else if (type == 115) {
			scale *= 1.4f;
		}
		else if (type == 116) {
			scale *= 1.4f;
		}
		else if (type == 118) {
			damage += 10;
			defense += 14;
			lifeMax *= 3;
		}
		else if (type == 222) {
			scale *= 1.2f;
		}
		else if (type == 245) {
			canDisplayBuffs = false;
			scale *= 0.5f;
		}
		else if (type == 246) {
			canDisplayBuffs = false;
			scale *= 0.5f;
		}
		else if (type == 247 || type == 248) {
			canDisplayBuffs = false;
			scale *= 0.5f;
		}
		else if (type == 249) {
			scale *= 0.5f;
		}
		else if (type == 262) {
			scale *= 1.3f;
		}
		else if (type == 266) {
			defense = (int)((double)defense * 1.5);
			damage = (int)((double)damage * 1.2);
			scale *= 1.1f;
		}
		else if (type == 125) {
			scale *= 0.8f;
		}
		else if (type == 126) {
			scale *= 0.8f;
		}
		else if (type == 127) {
			scale *= 1.1f;
		}
		else if (type == 128) {
			scale *= 1.1f;
		}
		else if (type == 129) {
			scale *= 1.1f;
		}
		else if (type == 130) {
			scale *= 1.1f;
		}
		else if (type == 131) {
			scale *= 1.1f;
		}
		else if (type == 134) {
			scale *= 1.3f;
		}
		else if (type == 135) {
			scale *= 1.3f;
		}
		else if (type == 136) {
			scale *= 1.3f;
		}
		else {
			if (type != 139)
				return;

			scale *= 1.6f;
		}

		if (IsABestiaryIconDummy) {
			scale = num;
			return;
		}

		width = (int)((float)width * scale);
		height = (int)((float)height * scale);
	}

