			vector.Normalize();
			vector *= num2;
			int num3 = (int)(10f * scale);
			if (type == 176)
				num3 = (int)(30f * scale);

			int num4 = 55;
			int num5 = Projectile.NewProjectile(GetSpawnSource_ForProjectile(), base.Center.X, base.Center.Y, vector.X, vector.Y, num4, num3, 0f, Main.myPlayer);
			Main.projectile[num5].timeLeft = 300;
		}
