						num3 = 17;

					if (num3 < 17 || num3 > 23)
						num3 = 17;

					frameCounter++;
					if (frameCounter >= 5.0) {
						frameCounter = 0.0;
						num3++;
						if (num4 < 40f && num3 > 19)
							num3 = 19;

						if (num3 > 23)
							num3 = 23;
					}
				}
				else if (ai[3] == 1f) {
					if (num3 < 24 || num3 > 29)
						num3 = 24;

					frameCounter++;
					if (frameCounter >= 5.0) {
						frameCounter = 0.0;
						num3++;
						if (num3 > 29)
							num3 = 29;
					}
				}
				else {
					if (num3 < 17 || num3 > 23)
						num3 = 17;

					frameCounter++;
					if (frameCounter >= 6.0) {
						frameCounter = 0.0;
						switch (num3) {
							case 17:
								num3 = 22;
								break;
							case 22:
								num3 = 23;
								break;
							default:
								num3 = 17;
								break;
						}
					}

					if (num3 >= Main.npcFrameCount[type])
						num3 = 0;
				}

				frame.Y = num3 * num;
				break;
			}
		}

		if (aiStyle == 39 && type != 417) {
			if (ai[0] == 0f) {
				rotation = 0f;
				if (velocity.Y == 0f)
					spriteDirection = direction;
				else if (velocity.Y < 0f)
					frameCounter = 0.0;

				frameCounter += Math.Abs(velocity.X) * 1.1f;
				if (frameCounter < 6.0)
					frame.Y = 0;
				else if (frameCounter < 12.0)
					frame.Y = num;
				else if (frameCounter < 18.0)
					frame.Y = num * 2;
				else if (frameCounter < 24.0)
					frame.Y = num * 3;
				else if (frameCounter < 32.0)
					frame.Y = num * 4;
				else
					frameCounter = 0.0;
			}
			else if (ai[0] == 1f) {
				frameCounter = 0.0;
				if (ai[1] < 10f)
					frame.Y = num * 5;
				else if (ai[1] < 20f)
					frame.Y = num * 6;
				else
					frame.Y = num * 7;
			}
			else if (ai[0] == 5f) {
				frameCounter = 0.0;
				if (ai[1] < 10f)
					frame.Y = num * 7;
				else if (ai[1] < 20f)
					frame.Y = num * 6;
				else
					frame.Y = num * 5;
			}
			else {
				frameCounter = 0.0;
				frame.Y = num * 7;
			}
		}

		position -= netOffset;
	}

	private static int FindFrame_FromSequence(int sequenceFrame, int[] frames)
	{
		int num = sequenceFrame;
		if (num >= frames.Length)
			num = frames.Length - 1;

		return frames[num];
	}

	private static int FindFrame_Deerclops_GetAttack1Frame(int sequenceFrame) => FindFrame_FromSequence(sequenceFrame, _deerclopsAttack1Frames);
	private static int FindFrame_Deerclops_GetAttack2Frame(int sequenceFrame) => FindFrame_FromSequence(sequenceFrame, _deerclopsAttack2Frames);
	private static int FindFrame_Deerclops_GetAttack3Frame(int sequenceFrame) => FindFrame_FromSequence(sequenceFrame, _deerclopsAttack3Frames);

	public void SimpleFlyMovement(Vector2 desiredVelocity, float moveSpeed)
	{
		if (velocity.X < desiredVelocity.X) {
			velocity.X += moveSpeed;
			if (velocity.X < 0f && desiredVelocity.X > 0f)
				velocity.X += moveSpeed;
		}
		else if (velocity.X > desiredVelocity.X) {
			velocity.X -= moveSpeed;
			if (velocity.X > 0f && desiredVelocity.X < 0f)
				velocity.X -= moveSpeed;
		}

		if (velocity.Y < desiredVelocity.Y) {
			velocity.Y += moveSpeed;
			if (velocity.Y < 0f && desiredVelocity.Y > 0f)
				velocity.Y += moveSpeed;
		}
		else if (velocity.Y > desiredVelocity.Y) {
			velocity.Y -= moveSpeed;
			if (velocity.Y > 0f && desiredVelocity.Y < 0f)
				velocity.Y -= moveSpeed;
		}
	}

	/// <summary>
	/// Spawns a <see cref="CombatText"/> indicating the NPC healed <paramref name="healAmount"/> life and syncs it if <paramref name="broadcast"/> is true.
	/// <para/> Note that this doesn't actually heal the NPC, it only spawns the floating text. To heal an NPC, <see cref="NPC.life"/> must be increased without exceeding <see cref="NPC.lifeMax"/>, <see cref="HealEffect(int, bool)"/> should be called, and <see cref="NPC.netUpdate"/> should be set to true.
	/// <para/> Since the server has ownership over NPC, this should only be called on the server in multiplayer situations.
	/// </summary>
	public void HealEffect(int healAmount, bool broadcast = true)
	{
		HealEffect(new Rectangle((int)position.X, (int)position.Y, width, height), healAmount, broadcast);
	}

	/// <summary>
	/// <inheritdoc cref="HealEffect(int, bool)" />
	/// <br/><br/>This particular overload allows customizing the spawn location of the text.
	/// </summary>
	public static void HealEffect(Rectangle r, int healAmount, bool broadcast = true)
	{
		if (broadcast && Main.netMode == 2)
			NetMessage.SendData(81, -1, -1, null, (int)CombatText.HealLife.PackedValue, r.Center.X, r.Center.Y, healAmount);
		else
			CombatText.NewText(r, CombatText.HealLife, healAmount);
	}

	public int FindClosestPlayer()
	{
		float distanceToPlayer;
		return FindClosestPlayer(out distanceToPlayer);
	}

	public int FindClosestPlayer(out float distanceToPlayer)
	{
		Vector2 center = base.Center;
		float num = float.MaxValue;
		int num2 = -1;
		for (int i = 0; i < 255; i++) {
			Player player = Main.player[i];
			if (player.active && !player.dead && !player.ghost) {
				float num3 = Vector2.DistanceSquared(center, player.Center);
				if (num3 < num) {
					num = num3;
					num2 = i;
				}
			}
		}

		if (num2 < 0) {
			for (int j = 0; j < 255; j++) {
				Player player = Main.player[j];
				if (player.active) {
					float num4 = Vector2.DistanceSquared(center, player.Center);
					if (num4 < num) {
						num = num4;
						num2 = j;
					}
				}
			}
		}

		distanceToPlayer = (float)Math.Sqrt(num);
		return num2;
	}

