						int k;
						for (k = (int)(base.Center.Y / 16f) + Main.rand.Next(-50, 51); k < Main.maxTilesY - 200 && !WorldGen.SolidTile(num5, k); k++) {
						}

						k--;
						if (!WorldGen.SolidTile(num5, k)) {
							int num6 = NewNPC(GetSpawnSourceForNPCFromNPCAI(), num5 * 16 + 8, k * 16, 32);
