								NetMessage.SendData(23, -1, -1, null, num6);

							break;
						}
					}
				}
			}
		}

		if (!NPCLoader.CheckDead(this))
			return;

		noSpawnCycle = true;
		if (townNPC && type != 37 && type != 453) {
			if (Main.netMode != 2)
				NPCLuck();

			bool flag = true;
			NetworkText fullNetName = GetFullNetName();
			int num7 = 19;
