				// Modder might have already used WithFormatArgs/BoundArgs to fill out custom name as well.
				custom = customDeathMessage.BoundArgs != null ? customDeathMessage.ToNetworkText() : customDeathMessage.ToNetworkText(GetFullNetName());
			}
			bool skipMessage = NPCLoader.ModifyDeathMessage(this, ref custom, ref color);
