	//TML: Added 'typeName' parameter.
	private void DoDeathEvents_DropBossPotionsAndHearts(ref string typeName)
	{
		int stack = Main.rand.Next(5, 16);
		int num = 28;
		if (type == 113)
			num = 188;
		else if (type == 35)
			num = 188;
		else if (type == 668)
			num = 188;
		else if (type == 222)
			num = 1134;
		else if (type == 657)
			num = 499;
		else if (type > 113 && type < 222)
			num = 499;
		else if (type == 636)
			num = 499;
		else if (type == 245 || type == 262)
			num = 499;
		else if (type == 370)
			num = 499;
		else if (type == 395)
			num = 499;
		else if (type == 439)
			num = 499;
		else if (type == 398)
			num = 3544;

		int num2 = Main.rand.Next(5) + 5;

		NPCLoader.BossLoot(this, ref typeName, ref num);
		NPCLoader.BossLoot(this, ref num, ref stack, ref num2);

		if (stack > 0 && num > 0)
			Item.NewItem(GetItemSource_Loot(), (int)position.X, (int)position.Y, width, height, num, stack);

		for (int i = 0; i < num2; i++) {
			Item.NewItem(GetItemSource_Loot(), (int)position.X, (int)position.Y, width, height, 58);
		}

		if (type == 4)
			EoCKilledToday = true;
		else if (type == 113)
			WoFKilledToday = true;

		if (EoCKilledToday && WoFKilledToday) {
			ResetBadgerHatTime();
			Item.NewItem(GetItemSource_Loot(), (int)position.X, (int)position.Y, width, height, 5004);
		}
	}

	//TML: Added 'typeName' parameter.
	private void DoDeathEvents_CelebrateBossDeath(string typeName)
	{
		NPCDamageTracker.BossKilled(this);
		Color bossOrEvent = ChatColors.BossOrEvent;
		NetworkText custom = null;
		if(ModNPC?.DeathMessage is LocalizedText customDeathMessage) {
			// Modder might have already used WithFormatArgs/BoundArgs to fill out custom boss fight name as well.
			custom = customDeathMessage.BoundArgs != null ? customDeathMessage.ToNetworkText() : customDeathMessage.ToNetworkText(GetFullNetName());
		}
		// Note: typeName comes from NPC.TypeName->NPCLoader.ModifyTypeName and NPCLoader.BossLoot, but is just a literal string and won't be localized on other clients properly if used, so it is not used in DeathMessage.
		bool skipMessage = NPCLoader.ModifyDeathMessage(this, ref custom, ref bossOrEvent);
		if (skipMessage) {
		}
		else if (custom != null) {
			if (Main.netMode == 0)
				Main.NewText(custom.ToString(), bossOrEvent);
			else if (Main.netMode == 2)
				ChatHelper.BroadcastChatMessage(custom, bossOrEvent);
		}
		else
		if (type == 125 || type == 126)
			ChatHelper.BroadcastChatMessage(NetworkText.FromKey("Announcement.HasBeenDefeated_Plural", NetworkText.FromKey("Enemies.TheTwins")), bossOrEvent);
		else if (type == 398)
			ChatHelper.BroadcastChatMessage(NetworkText.FromKey("Announcement.HasBeenDefeated_Single", NetworkText.FromKey("Enemies.MoonLord")), bossOrEvent);
		else
			ChatHelper.BroadcastChatMessage(NetworkText.FromKey("Announcement.HasBeenDefeated_Single", GetTypeNetName()), bossOrEvent);
	}

	private void CreateBrickBoxForWallOfFlesh()
	{
		int num = (int)(position.X + (float)(width / 2)) / 16;
		int num2 = (int)(position.Y + (float)(height / 2)) / 16;
		int num3 = width / 2 / 16 + 1;
		for (int i = num - num3; i <= num + num3; i++) {
			for (int j = num2 - num3; j <= num2 + num3; j++) {
				if ((i == num - num3 || i == num + num3 || j == num2 - num3 || j == num2 + num3) && !Main.tile[i, j].active()) {
					Main.tile[i, j].type = (ushort)(WorldGen.crimson ? 347 : 140);
					Main.tile[i, j].active(active: true);
				}

				Main.tile[i, j].lava(lava: false);
				Main.tile[i, j].liquid = 0;
				if (Main.netMode == 2)
					NetMessage.SendTileSquare(-1, i, j);
				else
					WorldGen.SquareTileFrame(i, j);
			}
		}
	}

