					if (ignorePillarsAndMoonlordCountdown) {
						switch (Main.npc[i].type) {
							case 422:
							case 493:
							case 507:
							case 517:
								continue;
						}
					}

					flag = true;
				}
			}
		}

		return flag;
	}

