	internal int StrikeNPCNoInteraction(int Damage, float knockBack, int hitDirection)
	{
		/*
		if (Main.netMode == 0)
			ignorePlayerInteractions++;

		return StrikeNPC(Damage, knockBack, hitDirection, crit, noEffect, fromNet, 255);
		*/
		return StrikeNPC(Damage, knockBack, hitDirection, noPlayerInteraction: true);
	}

	/*
	public int KeyBrandStrike(int plr, int dmg, Vector2 bestSwordSpot)
	*/
	public float KeyBrandStrike(int plr, float dmg, Vector2 bestSwordSpot)
	{
		float t = (float)life / (float)lifeMax;
		float lerpValue = Utils.GetLerpValue(1f, 0.1f, t, clamped: true);
		float num = 1f * lerpValue;
		/*
		dmg = (int)((float)dmg * (1f + num));
		*/
		dmg = (dmg * (1f + num));
		Vector2 positionInWorld = base.Hitbox.ClosestPointInRect(bestSwordSpot);
		ParticleOrchestrator.RequestParticleSpawn(clientOnly: false, ParticleOrchestraType.Keybrand, new ParticleOrchestraSettings {
			PositionInWorld = positionInWorld
		}, plr);

		return dmg;
	}

	internal int StrikeNPC(int Damage, float knockBack, int hitDirection, bool crit = false, bool fromNet = false, bool noPlayerInteraction = false)
	{
		return StrikeNPC(CalculateStrikeFromLegacyValues(Damage, knockBack, hitDirection, crit), fromNet, noPlayerInteraction);
	}

	internal HitInfo CalculateStrikeFromLegacyValues(int Damage, float knockBack, int hitDirection, bool crit)
	{
		HitInfo hit;
		if (Damage == 9999) {
			hit = new HitInfo {
				Crit = crit,
				Knockback = knockBack,
				HitDirection = hitDirection,
				InstantKill = true
			};
		}
		else {
			var modifiers = GetIncomingStrikeModifiers(DamageClass.Default, hitDirection, ignoreArmorDebuffs: true);
			hit = modifiers.ToHitInfo(Damage, crit, knockBack, damageVariation: false);
		}

		NetMessage.SetLegacyStrike(hit);
		return hit;
	}

	/// <summary>
	/// Initializes a <see cref="HitModifiers"/> calculation with the properties of this NPC, including calling <see cref="NPCLoader.ModifyIncomingHit"/>
	/// </summary>
	/// <param name="damageType">The DamageType of the hit.</param>
	/// <param name="hitDirection">The direction to apply knockback. If 0, no knockback will be applied.</param>
	/// <param name="ignoreArmorDebuffs">Ignores <see cref="ichor"/> and <see cref="betsysCurse"/>. Only used for legacy vanilla codepaths.</param>
	/// <returns></returns>
	public HitModifiers GetIncomingStrikeModifiers(DamageClass damageType, int hitDirection, bool ignoreArmorDebuffs = false)
	{
		var modifiers = new HitModifiers() with {
			DamageType = damageType,
			HitDirection = hitDirection,
			SuperArmor = SuperArmor
		};

		modifiers.FinalDamage *= takenDamageMultiplier;

		if (defense >= 0)
			modifiers.Defense.Base += defense;
		else
			modifiers.FlatBonusDamage += -defense;

		if (!ignoreArmorDebuffs) {
			if (ichor)
				modifiers.Defense.Flat -= 15;

			if (betsysCurse)
				modifiers.Defense.Flat -= 40;
		}

		if (onFire2)
			modifiers.Knockback += 0.1f;

		modifiers.Knockback *= knockBackResist;
		if (knockBackResist == 0)
			modifiers.DisableKnockback();

		NPCLoader.ModifyIncomingHit(this, ref modifiers);
		return modifiers;
	}

	/// <summary>
	/// Runs <see cref="NPCLoader.ModifyIncomingHit"/> hooks and and does the full damage calculations. <br/>
	/// The result <see cref="HitInfo.Damage"/> will contain the health the NPC will lose when applied. <br/>
	/// </summary>
	/// <param name="damage">The damage to deal to the NPC, before modifications, defense, resistances etc</param>
	/// <param name="hitDirection">The hit direction of the resulting strike (1 or -1)</param>
	/// <param name="crit">Defaults to false</param>
	/// <param name="knockBack">Defaults to 0</param>
	/// <param name="damageType">Defaults to <see cref="DamageClass.Default"/></param>
	/// <param name="damageVariation">Whether to apply damage variation. Defaults to false.</param>
	/// <param name="luck">Luck modifier to produce weight damageVariation towards higher (positive) or lower (negative) values. Defaults to 0</param>
	/// <returns>A <see cref="HitInfo"/> for use with <see cref="StrikeNPC(HitInfo, bool, bool)"/> and <see cref="NetMessage.SendStrikeNPC"/></returns>
	/// <remarks>
	/// Note: This method doesn't include entity-related hit modifying hooks and shouldn't be used in normal contexts.
	/// <br/><br/> Consider using <see cref="StrikeOtherNPC"/> instead.
	/// </remarks>
	public HitInfo CalculateHitInfo(int damage, int hitDirection, bool crit = false, float knockBack = 0f, DamageClass damageType = null, bool damageVariation = false, float luck = 0) {
		return GetIncomingStrikeModifiers(damageType, hitDirection).ToHitInfo(damage, crit, knockBack, damageVariation, luck);
	}

	/// <summary>
	/// Calls <see cref="CalculateHitInfo"/>, <see cref="StrikeNPC(HitInfo, bool, bool)"/> and then <see cref="NetMessage.SendStrikeNPC"/> (in multiplayer) <br/>
	/// </summary>
	/// <param name="damage">The damage to deal to the NPC, before modifications, defense, resistances etc</param>
	/// <param name="hitDirection">The hit direction of the resulting strike (1 or -1)</param>
	/// <param name="crit">Defaults to false</param>
	/// <param name="knockBack">Defaults to 0</param>
	/// <param name="damageType">Defaults to <see cref="DamageClass.Default"/></param>
	/// <param name="damageVariation">Whether to apply damage variation. Defaults to false.</param>
	/// <param name="luck">Luck modifier to produce weight damageVariation towards higher (positive) or lower (negative) values. Defaults to 0</param>
	/// <param name="noPlayerInteraction">Prevents <see cref="PlayerInteraction(int)"/> from being called in single player. In multiplayer, player interaction is handled by the server.</param>
	/// <returns>The actual health lost by the NPC. Normally this is <see cref="HitInfo.Damage"/> but it is capped at the current health of the NPC, and represents the actual damage dealt in the case of <see cref="HitInfo.InstantKill"/> </returns>
	public int SimpleStrikeNPC(int damage, int hitDirection, bool crit = false, float knockBack = 0f, DamageClass damageType = null, bool damageVariation = false, float luck = 0, bool noPlayerInteraction = false)
	{
		var hit = CalculateHitInfo(damage, hitDirection, crit, knockBack, damageType, damageVariation, luck);
		int damageDone = StrikeNPC(hit, fromNet: false, noPlayerInteraction);
		if (Main.netMode != NetmodeID.SinglePlayer)
			NetMessage.SendStrikeNPC(this, hit);

		return damageDone;
	}

	/// <summary>
	/// Helper method for calling <see cref="StrikeNPC(HitInfo, bool, bool)"/> with a <see cref="HitInfo.InstantKill"/> strike. <br/>
	/// Use to butcher your own NPCs. <br/>
	/// Not recommended for use on multiplayer clients because the net packet will trigger <see cref="PlayerInteraction"/> on the server.
	/// </summary>
	public void StrikeInstantKill()
	{
		var hit = new NPC.HitInfo() { InstantKill = true };
		StrikeNPC(hit, noPlayerInteraction: true);
		if (Main.netMode != NetmodeID.SinglePlayer)
			NetMessage.SendStrikeNPC(this, hit);
	}

	/// <summary>
	/// Directly deals damage to the NPC, spawns combat text, plays hit sound, deals knockback based on the provided <see cref="HitInfo"/><br/>
	/// Calls <see cref="HitEffect(HitInfo)"/> and associated hooks after dealing damage.<br/>
	/// Calls <see cref="checkDead"/><br/>
	/// Does not automatically send packets. Use <see cref="NetMessage.SendStrikeNPC"/> to synchronize hits.
	/// </summary>
	/// <param name="hit">The parameters of the hit. Normally obtained via <see cref="NPC.HitModifiers"/> or <see cref="CalculateHitInfo"/></param>
	/// <param name="fromNet">true if this strike came from another client over the network. Just changes the combat text to be darker in color.</param>
	/// <param name="noPlayerInteraction">Prevents <see cref="PlayerInteraction(int)"/> from being called in single player. In multiplayer, player interaction is handled by the server.</param>
	/// <returns>The actual health lost by the NPC. Normally this is <see cref="HitInfo.Damage"/> but it is capped at the current health of the NPC, and represents the actual damage dealt in the case of <see cref="HitInfo.InstantKill"/> </returns>
	public int StrikeNPC(HitInfo hit, bool fromNet = false, bool noPlayerInteraction = false, int owner = -1)
	{
		if (owner < 0)
			owner = Main.myPlayer;

		if (Main.onlyShimmerOceanWorlds && type == 680 && GivenName == "Slimefors")
 			return 0;

		bool flag = Main.netMode == 0;
		/*
		if (flag && ignorePlayerInteractions > 0) {
			ignorePlayerInteractions--;
			flag = false;
		}
		*/
		flag &= !noPlayerInteraction;

		if (!active || life <= 0)
			return 0;

		NetUpdateLowPriority();
		double num = hit.Damage;
		bool crit = hit.Crit;
		int hitDirection = hit.HitDirection;
		if (hit.InstantKill)
			num = realLife > 0 ? Main.npc[realLife].life : life;

		/*
		double num = Damage;
		num = Main.CalculateDamageNPCsTake((int)num, defense);
		if (crit)
			num *= 2.0;

		if (RedHatSkeletronAdjustmentsEnabled()) {
			num = (int)(num * 0.699999988079071);
			if (num < 1.0)
				num = 1.0;
		}

		if (takenDamageMultiplier > 1f)
			num *= (double)takenDamageMultiplier;

		if ((takenDamageMultiplier > 1f || Damage != 9999) && lifeMax > 1) {
		*/
		if (!hit.HideCombatText && !hit.InstantKill && lifeMax > 1 && !HideStrikeDamage) {
			if (friendly) {
				Color color = (crit ? CombatText.DamagedFriendlyCrit : CombatText.DamagedFriendly);
				CombatText.NewText(new Rectangle((int)position.X, (int)position.Y, width, height), color, (int)num, crit);
			}
			else {
				Color color2 = (crit ? CombatText.DamagedHostileCrit : CombatText.DamagedHostile);
				if (fromNet)
					color2 = (crit ? CombatText.OthersDamagedHostileCrit : CombatText.OthersDamagedHostile);

				CombatText.NewText(new Rectangle((int)position.X, (int)position.Y, width, height), color2, (int)num, crit);
			}
		}

		if (num >= 1.0) {
			if (flag)
				PlayerInteraction(Main.myPlayer);

			justHit = true;
			if ((type == 438 || type == 379) && Main.netMode != 1) {
				int num2 = (int)(0f - ai[3] - 1f);
				if (num2 > -1 && Main.npc[num2].localAI[0] == 0f)
					Main.npc[num2].localAI[0] = 1f;
			}

			if (townNPC) {
				if (aiStyle == 7 && (ai[0] == 3f || ai[0] == 4f || ai[0] == 16f || ai[0] == 17f)) {
					NPC nPC = Main.npc[(int)ai[2]];
					if (nPC.active) {
						nPC.ai[0] = 1f;
						nPC.ai[1] = 300 + Main.rand.Next(300);
						nPC.ai[2] = 0f;
						nPC.localAI[3] = 0f;
						nPC.direction = hitDirection;
						nPC.netUpdate = true;
					}
				}

				ai[0] = 1f;
				ai[1] = 300 + Main.rand.Next(300);
				ai[2] = 0f;
				localAI[3] = 0f;
				direction = hitDirection;
				netUpdate = true;
			}

			if (Main.netMode != 1 && aiStyle == 87 && ai[0] == 0f) {
				ai[0] = 1f;
				ai[1] = 0f;
				netUpdate = true;
			}

			if (aiStyle == 8) {
				if (Main.netMode != 1) {
					if (type == 172) {
						ai[0] = 450f;
					}
					else if (type == 283 || type == 284) {
						if (Main.rand.Next(2) == 0) {
							ai[0] = 390f;
							netUpdate = true;
						}
					}
					else if (type == 533) {
						if (Main.rand.Next(3) != 0) {
							ai[0] = 181f;
							netUpdate = true;
						}
					}
					else {
						ai[0] = 400f;
					}

					TargetClosest();
				}

				if (type == 693) {
					localAI[1] = localAI[0] + 250f;
					localAI[2] = 10f;
				}
			}

			if (aiStyle == 97 && Main.netMode != 1) {
				localAI[1] = 1f;
				TargetClosest();
			}

			if (type == 371) {
				num = 0.0;
				ai[0] = 1f;
				ai[1] = 4f;
				dontTakeDamage = true;
			}

			if (type == 346 && (double)life >= (double)lifeMax * 0.5 && (double)life - num < (double)lifeMax * 0.5)
				Gore.NewGore(position, velocity, 517);

			if (type == 184)
				localAI[0] = 60f;

			if (type == 535)
				localAI[0] = 60f;

			if (type == 185)
				localAI[0] = 1f;

			if (!immortal) {
				/*
				bool flag2 = Damage >= 9999 && owner == 255;
				*/
				bool flag2 = hit.InstantKill && owner == 255;
				if (Main.netMode != 1 && !flag2)
					NPCDamageTracker.AddDamage(this, owner, (int)num);

				if (realLife >= 0) {
					Main.npc[realLife].life -= (int)num;
					life = Main.npc[realLife].life;
					lifeMax = Main.npc[realLife].lifeMax;
				}
				else {
					life -= (int)num;
				}
			}
			/*
			if (knockBack > 0f && knockBackResist > 0f) {
				float num3 = knockBack * knockBackResist;
				if (onFire2)
					num3 *= 1.1f;
			*/
			if (hit.Knockback > 0) {
				float num3 = hit.Knockback;

				if (num3 > 8f) {
					float num4 = num3 - 8f;
					num4 *= 0.9f;
					num3 = 8f + num4;
				}

				if (num3 > 10f) {
					float num5 = num3 - 10f;
					num5 *= 0.8f;
					num3 = 10f + num5;
				}

				if (num3 > 12f) {
					float num6 = num3 - 12f;
					num6 *= 0.7f;
					num3 = 12f + num6;
				}

				if (num3 > 14f) {
					float num7 = num3 - 14f;
					num7 *= 0.6f;
					num3 = 14f + num7;
				}

				if (num3 > 16f)
					num3 = 16f;

				if (crit)
					num3 *= 1.4f;

				int num8 = (int)num * 10;
				if (Main.expertMode)
					num8 = (int)num * 15;

				if (num8 > lifeMax) {
					if (hitDirection < 0 && velocity.X > 0f - num3) {
						if (velocity.X > 0f)
							velocity.X -= num3;

						velocity.X -= num3;
						if (velocity.X < 0f - num3)
							velocity.X = 0f - num3;
					}
					else if (hitDirection > 0 && velocity.X < num3) {
						if (velocity.X < 0f)
							velocity.X += num3;

						velocity.X += num3;
						if (velocity.X > num3)
							velocity.X = num3;
					}

					if (type == 185)
						num3 *= 1.5f;

					num3 = (noGravity ? (num3 * -0.5f) : (num3 * -0.75f));
					if (velocity.Y > num3) {
						velocity.Y += num3;
						if (velocity.Y < num3)
							velocity.Y = num3;
					}
				}
				else {
					if (!noGravity)
						velocity.Y = (0f - num3) * 0.75f * knockBackResist;
					else
						velocity.Y = (0f - num3) * 0.5f * knockBackResist;

					velocity.X = num3 * (float)hitDirection * knockBackResist;
				}
			}

			if ((type == 113 || type == 114) && life <= 0) {
				for (int i = 0; i < Main.maxNPCs; i++) {
					if (Main.npc[i].active && (Main.npc[i].type == 113 || Main.npc[i].type == 114))
						Main.npc[i].HitEffect(hitDirection, num, hit.InstantKill);
				}
			}
			else {
				HitEffect(hit);
			}

			if (type == 1) {
				switch ((int)ai[1]) {
					case 5507:
						SoundEngine.PlaySound(SoundID.BalloonHurt, position);
						break;
					case 5502:
						SoundEngine.PlaySound(SoundID.CatHurt, position);
						break;
					case 5485:
						if (Main.rand.Next(5) == 0)
							SoundEngine.PlaySound(SoundID.ChickenHurtRare, position);
						else
							SoundEngine.PlaySound(SoundID.ChickenHurt, position);
						break;
					case 5484:
						SoundEngine.PlaySound(SoundID.BellHurt, position);
						break;
					case 5506:
						SoundEngine.PlaySound(SoundID.CrowHurt, position);
						break;
					case 5503:
						SoundEngine.PlaySound(SoundID.DogHurt, position);
						break;
					case 5534:
						SoundEngine.PlaySound(SoundID.FairyHurt, position);
						break;
					case 5499:
						SoundEngine.PlaySound(SoundID.FrogHurt, position);
						break;
					case 5500:
						SoundEngine.PlaySound(SoundID.GoatHurt, position);
						break;
					case 5505:
						SoundEngine.PlaySound(SoundID.GoblinHurt, position);
						break;
					case 5501:
						SoundEngine.PlaySound(SoundID.RetroHurt, position);
						break;
					case 5504:
						SoundEngine.PlaySound(SoundID.TurkeyHurt, position);
						break;
					case 5508:
						SoundEngine.PlaySound(SoundID.UndeadHurt, position);
						break;
					case 5509:
						SoundEngine.PlaySound(SoundID.VampireHurt, position);
						break;
					default:
						if (HitSound != null)
							SoundEngine.PlaySound(HitSound, position);
						break;
				}
			}
			else if (HitSound != null) {
				SoundEngine.PlaySound(HitSound, position);
			}

			if (realLife >= 0)
				Main.npc[realLife].checkDead();
			else
				checkDead();

			return (int)num;
		}

		return 0;
	}

	public static void LadyBugKilled(Vector2 Position, bool GoldLadyBug = false)
	{
		Main.ladyBugRainBoost += ladyBugRainTime;
		if (Main.ladyBugRainBoost > maximumAmountOfTimesLadyBugRainCanStack)
			Main.ladyBugRainBoost = maximumAmountOfTimesLadyBugRainCanStack;

		int myPlayer = Main.myPlayer;
		if (!Main.player[myPlayer].active || Main.player[myPlayer].dead)
			return;

		Vector2 vector = Position - Main.player[myPlayer].Center;
		int num = 400;
		if (vector.Length() < (float)num) {
			if (vector.Length() < 100f)
				vector = default(Vector2);

			double num2 = 1.0 - (double)vector.Length() / (double)num;
			int num3 = (int)((double)ladyBugBadLuckTime * num2);
			if (GoldLadyBug)
				num3 *= 2;

			if (num3 < Main.player[myPlayer].ladyBugLuckTimeLeft) {
				Main.player[myPlayer].ladyBugLuckTimeLeft = num3;
				Main.player[myPlayer].luckNeedsSync = true;
			}
		}
	}

	private void LadyBugLuck(int plr, bool GoldLadyBug = false)
	{
		if (releaseOwner != 255 || Main.player[plr].ladyBugLuckTimeLeft < 0)
			return;

		Vector2 vector = base.Center - Main.player[plr].Center;
		int num = 800;
		if (vector.Length() < (float)num) {
			if (vector.Length() < 30f)
				vector = default(Vector2);

			double x = 1.0 - (double)vector.Length() / (double)num;
			x = Math.Pow(x, 6.0);
			int num2 = (int)((double)ladyBugGoodLuckTime * x);
			if (GoldLadyBug)
				num2 *= 2;

			if (num2 > Main.player[plr].ladyBugLuckTimeLeft) {
				Main.player[plr].ladyBugLuckTimeLeft = num2;
				Main.player[plr].luckNeedsSync = true;
			}
		}
	}

	private void NPCLuck()
	{
		int myPlayer = Main.myPlayer;
		if (type == 22) {
			if (Main.player[myPlayer].ladyBugLuckTimeLeft >= 0 && Main.player[myPlayer].active && !Main.player[myPlayer].dead) {
				int num = ladyBugGoodLuckTime / 3;
				if (num > Main.player[myPlayer].ladyBugLuckTimeLeft) {
					Main.player[myPlayer].ladyBugLuckTimeLeft = num;
					Main.player[myPlayer].luckNeedsSync = true;
				}
			}
		}
		else if (type != 54 && Main.player[myPlayer].active && !Main.player[myPlayer].dead) {
			int num2 = ladyBugBadLuckTime / 3;
			if (num2 < Main.player[myPlayer].ladyBugLuckTimeLeft) {
				Main.player[myPlayer].ladyBugLuckTimeLeft = num2;
				Main.player[myPlayer].luckNeedsSync = true;
			}
		}
	}

	// Added instantKill parameter
	public void HitEffect(int hitDirection = 0, double dmg = 10.0, bool? instantKill = null)
	{
		instantKill ??= dmg == 9999;
		HitEffect(new HitInfo {
			DamageType = DamageClass.Default,
			SourceDamage = instantKill.Value ? 1 : (int)dmg,
			Damage = instantKill.Value ? 1 : (int)dmg,
			Crit = false,
			HitDirection = hitDirection,
			Knockback = 0,
			InstantKill = instantKill.Value
		});
	}

	public void HitEffect(HitInfo hit)
	{
		using var _ = IEntitySource.PushFallback(thisEntitySourceCache);
		VanillaHitEffect(hit.HitDirection, hit.Damage, hit.InstantKill);
		NPCLoader.HitEffect(this, hit);
	}

