	/// <summary>
	/// Returns the number of active NPC in the world of the given NPC type (<see cref="NPC.type"/>).
	/// </summary>
	/// <param name="Type"></param>
	/// <returns></returns>
	public static int CountNPCS(int Type)
	{
		int num = 0;
		for (int i = 0; i < Main.maxNPCs; i++) {
			if (Main.npc[i].active && Main.npc[i].type == Type)
				num++;
		}

		return num;
	}

	public static bool AnyHelpfulFairies()
	{
		for (int i = 0; i < Main.maxNPCs; i++) {
			if (Main.npc[i].active && (Main.npc[i].type == 583 || Main.npc[i].type == 584 || Main.npc[i].type == 585) && Main.npc[i].ai[2] > 1f)
				return true;
		}

		return false;
	}

	private static bool AnyLifeCrystalSlimes()
	{
		for (int i = 0; i < Main.maxNPCs; i++) {
			if (Main.npc[i].active && Main.npc[i].type == 1 && Main.npc[i].ai[1] == 29f)
				return true;
		}

		return false;
	}

	/// <summary>
	/// Returns true if there are any active NPC in the world of the given NPC type (<see cref="NPC.type"/>).
	/// </summary>
	/// <param name="Type"></param>
	/// <returns></returns>
	public static bool AnyNPCs(int Type)
	{
		for (int i = 0; i < Main.maxNPCs; i++) {
			if (Main.npc[i].active && Main.npc[i].type == Type)
				return true;
		}

		return false;
	}

	/// <summary>
	/// Returns the index within <see cref="Main.npc"/> of the first active NPC in the world of the given NPC type (<see cref="NPC.type"/>). Returns -1 if not found.
	/// </summary>
	/// <param name="Type"></param>
	/// <returns></returns>
	public static int FindFirstNPC(int Type)
	{
		for (int i = 0; i < Main.maxNPCs; i++) {
			if (Main.npc[i].active && Main.npc[i].type == Type)
				return i;
		}

		return -1;
	}

	public static bool NearSpikeBall(int x, int y)
	{
		Rectangle rectangle = new Rectangle(x * 16 - 300, y * 16 - 300, 600, 600);
		for (int i = 0; i < Main.maxNPCs; i++) {
			if (Main.npc[i].active && Main.npc[i].aiStyle == 20) {
				Rectangle rectangle2 = new Rectangle((int)Main.npc[i].ai[1], (int)Main.npc[i].ai[2], 20, 20);
				if (rectangle.Intersects(rectangle2))
					return true;
			}
		}

		return false;
	}

	public int FindBuffIndex(int type)
	{
		if (buffImmune[type])
			return -1;

		for (int i = 0; i < maxBuffs; i++) {
			if (buffTime[i] >= 1 && buffType[i] == type)
				return i;
		}

		return -1;
	}

	/// <summary>
	/// Gives this NPC the provided buff. This accounts for if the NPC is immune to the buff.
	/// <br/> If the NPC already has the buff, the re-apply logic will happen. Vanilla buff types are found in <see cref="BuffID"/> and modded buffs are typically retrieved using <see cref="ModContent.BuffType{T}"/>.
	/// <br/> The quiet parameter will determine if the network sync message should happen. This should always stay false.
	/// </summary>
	/// <param name="type">The buff type</param>
	/// <param name="time">The desired buff time in ticks. 60 ticks is 1 second</param>
	/// <param name="quiet">If true, the network sync message is skipped.</param>
	public void AddBuff(int type, int time, bool quiet = false)
	{
		if (buffImmune[type])
			return;

		if (!quiet && Main.netMode == 1)
			NetMessage.SendData(53, -1, -1, null, whoAmI, type, time);

		int num = -1;
		for (int i = 0; i < maxBuffs; i++) {
			if (buffType[i] == type) {
				if (BuffLoader.ReApply(type, this, time, i)) // TODO: Adjust this for proper syncing
					return;

				if (buffTime[i] >= time)
					return;

				num = i;
				break;
			}
		}

		while (num == -1) {
			int num2 = -1;
			for (int j = 0; j < maxBuffs; j++) {
				if (!Main.debuff[buffType[j]]) {
					num2 = j;
					break;
				}
			}

			if (num2 == -1)
				return;

			for (int k = num2; k < maxBuffs; k++) {
				if (buffType[k] == 0) {
					num = k;
					break;
				}
			}

			if (num == -1)
				DelBuff(num2, quiet: true);
		}

		buffType[num] = type;
		buffTime[num] = time;
		if (!quiet && Main.netMode == 2)
			NetMessage.SendData(54, -1, -1, null, whoAmI);
	}

	/// <summary>
	/// Removes the buff type and shuffles the remaining buff indexes down to fill the gap. Note that only buffs contained in <see cref="BuffID.Sets.CanBeRemovedByNetMessage"/> can be removed with this method. The intention is that those specific buffs are "owned" by the player who inflicts them, so they can be freely removed by multiplayer clients.
	/// <br/><br/>  In all other cases code running on the server or in single player is in charge of the NPC debuffs and <see cref="NPC.DelBuff"/> should be used directly.
	/// </summary>
	/// <param name="buffTypeToRemove">The buff type</param>
	public void RequestBuffRemoval(int buffTypeToRemove)
	{
		if (buffTypeToRemove < 0 || !BuffID.Sets.CanBeRemovedByNetMessage[buffTypeToRemove])
			return;

		int num = FindBuffIndex(buffTypeToRemove);
		if (num != -1) {
			DelBuff(num);
			if (Main.netMode == 1)
				NetMessage.SendData(137, -1, -1, null, whoAmI, buffTypeToRemove);
		}
	}

	/// <summary>
	/// Removes the buff at the provided index and shuffles the remaining buff indexes down to fill the gap. The buff types and times will then be synced to clients. This method should only be called on the server or in single player.
	/// </summary>
	/// <param name="buffIndex">The index of the buff to remove.</param>
	public void DelBuff(int buffIndex, bool quiet = false)
	{
		buffTime[buffIndex] = 0;
		buffType[buffIndex] = 0;
		for (int i = 0; i < maxBuffs - 1; i++) {
			if (buffTime[i] == 0 || buffType[i] == 0) {
				for (int j = i + 1; j < maxBuffs; j++) {
					buffTime[j - 1] = buffTime[j];
					buffType[j - 1] = buffType[j];
					buffTime[j] = 0;
					buffType[j] = 0;
				}
			}
		}

		if (!quiet && Main.netMode == 2)
			NetMessage.SendData(54, -1, -1, null, whoAmI);
	}

	public Rectangle getRect() => new Rectangle((int)position.X, (int)position.Y, width, height);

	/// <summary>
	/// Returns true if this NPC should be considered an enemy to attack. Used by various player, projectile, mount, and town npc logic. For example homing projectiles like Chlorophyte bullet won't target friendly NPC, critters, or NPC that are currently flagged as invulnerable. Note that the <paramref name="attacker"/> parameter is unused.
	/// <para/> The logic checks that the NPC meets all of the following criteria: <see cref="NPC.active"/>, <see cref="chaseable"/>, <see cref="lifeMax"/> > 5 (to ignore critters), <see cref="dontTakeDamage"/> (unless <paramref name="ignoreDontTakeDamage"/>) is true), not <see cref="friendly"/>, and not <see cref="immortal"/>.
	/// </summary>
	/// <param name="attacker"></param>
	/// <param name="ignoreDontTakeDamage"></param>
	/// <returns></returns>
	public bool CanBeChasedBy(object attacker = null, bool ignoreDontTakeDamage = false)
	{
		if (active && chaseable && lifeMax > 5 && (!dontTakeDamage || ignoreDontTakeDamage) && !friendly) {
			if (!DebugOptions.LetProjectilesAimAtTargetDummies)
				return !immortal;

			return true;
		}

		return false;
	}

	public bool HittableForOnHitRewards()
	{
		if (CountsAsACritter || immortal)
			return false;

		return true;
	}

