				lifeRegen = 0;

			lifeRegen -= 12;
		}

		if (bleeding) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			lifeRegen -= 24;
			if (num < 4)
				num = 4;
		}

		if (hemorrhage) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			lifeRegen -= 200;
			if (num < 40)
				num = 40;
		}

		if (onFire && (type != 1 || ai[1] != 8f || !Main.getGoodWorld)) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			lifeRegen -= 8;
			if (drippingSlime)
				lifeRegen -= 8;

			if (type == 1 && ai[1] == 9f)
				lifeRegen -= 16;
		}

		if (onFire3) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			lifeRegen -= 30;
			if (drippingSlime)
				lifeRegen -= 30;

			if (num < 5)
				num = 5;
		}

		if (onFrostBurn) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			lifeRegen -= 16;
			if (drippingSlime)
				lifeRegen -= 16;

			if (num < 2)
				num = 2;

			if (type == 1 && ai[1] == 9f)
				lifeRegen -= 16;
		}

		if (onFrostBurn2) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			lifeRegen -= 50;
			if (drippingSlime)
				lifeRegen -= 50;

			if (num < 10)
				num = 10;
		}

		if (onFire2) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			lifeRegen -= 48;
			if (drippingSlime)
				lifeRegen -= 48;

			if (num < 10)
				num = 10;
		}

		if (venom) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			lifeRegen -= 60;
			if (num < 15)
				num = 15;
		}

		if (shadowFlame) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			lifeRegen -= 30;
			if (drippingSlime)
				lifeRegen -= 30;

			if (num < 5)
				num = 5;
		}

		if (oiled && (onFire || onFire2 || onFire3 || onFrostBurn || onFrostBurn2 || shadowFlame)) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			lifeRegen -= 50;
			if (num < 10)
				num = 10;
		}

		if (javelined) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			int num2 = 0;
			int num3 = 1;
			for (int i = 0; i < 1000; i++) {
				if (Main.projectile[i].active && Main.projectile[i].type == 598 && Main.projectile[i].ai[0] == 1f && Main.projectile[i].ai[1] == (float)whoAmI)
					num2++;
			}

			lifeRegen -= num2 * 2 * 3;
			if (num < num2 * 3 / num3)
				num = num2 * 3 / num3;
		}

		if (tentacleSpiked) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			int num4 = 0;
			int num5 = 1;
			for (int j = 0; j < 1000; j++) {
				if (Main.projectile[j].active && Main.projectile[j].type == 971 && Main.projectile[j].ai[0] == 1f && Main.projectile[j].ai[1] == (float)whoAmI)
					num4++;
			}

			lifeRegen -= num4 * 2 * 3;
			if (num < num4 * 3 / num5)
				num = num4 * 3 / num5;
		}

		if (markedByEelWhip)
			ApplyEelWhipDoT();

		if (bloodButchered) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			int num6 = 0;
			int num7 = 1;
			for (int k = 0; k < 1000; k++) {
				if (Main.projectile[k].active && Main.projectile[k].type == 975 && Main.projectile[k].ai[0] == 1f && Main.projectile[k].ai[1] == (float)whoAmI)
					num6++;
			}

			lifeRegen -= num6 * 2 * 4;
			if (num < num6 * 4 / num7)
				num = num6 * 4 / num7;
		}

		if (daybreak) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			int num8 = 0;
			int num9 = 4;
			for (int l = 0; l < 1000; l++) {
				if (Main.projectile[l].active && Main.projectile[l].type == 636 && Main.projectile[l].ai[0] == 1f && Main.projectile[l].ai[1] == (float)whoAmI)
					num8++;
			}

			if (num8 == 0)
				num8 = 1;

			lifeRegen -= num8 * 2 * 100;
			if (num < num8 * 100 / num9)
				num = num8 * 100 / num9;
		}

		if (celled) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			int num10 = 0;
			for (int m = 0; m < 1000; m++) {
				if (Main.projectile[m].active && Main.projectile[m].type == 614 && Main.projectile[m].ai[0] == 1f && Main.projectile[m].ai[1] == (float)whoAmI)
					num10++;
			}

			lifeRegen -= num10 * 2 * 20;
			if (num < num10 * 20)
				num = num10 * 20 / 2;
		}

		if (dryadBane) {
			int num11 = 4;
			float num12 = 1f;
			if (lifeRegen > 0)
				lifeRegen = 0;

			if (downedBoss1)
				num12 += 0.1f;

			if (downedBoss2)
				num12 += 0.1f;

			if (downedBoss3)
				num12 += 0.1f;

			if (downedQueenBee)
				num12 += 0.1f;

			if (Main.hardMode)
				num12 += 0.4f;

			if (downedQueenSlime)
				num12 += 0.15f;

			if (downedMechBoss1)
				num12 += 0.15f;

			if (downedMechBoss2)
				num12 += 0.15f;

			if (downedMechBoss3)
				num12 += 0.15f;

			if (downedPlantBoss)
				num12 += 0.15f;

			if (downedGolemBoss)
				num12 += 0.15f;

			if (downedAncientCultist)
				num12 += 0.15f;

			if (downedEmpressOfLight)
				num12 += 0.15f;

			if (downedFishron)
				num12 += 0.15f;

			if (Main.infectedSeed)
				num11 *= 2;

			num11 = GetAttackDamage_ForTownNPC((float)num11 * num12);
			lifeRegen -= 2 * num11;
			if (num < num11)
				num = num11 / 3;
		}

		if (soulDrain && realLife == -1) {
			if (lifeRegen > 0)
				lifeRegen = 0;

			lifeRegen -= 50;
			if (num < 5)
				num = 5;
		}

		if (type == 59 && ai[1] == 174f && lavaWet)
			lifeRegen += 32;

		if (type == 1) {
			if (ai[1] == 29f)
				lifeRegen += 16;
			else if (ai[1] == 364f || ai[1] == 1104f || ai[1] == 365f || ai[1] == 1105f || ai[1] == 366f || ai[1] == 1106f)
				lifeRegen += 24;
		}

		NPCLoader.UpdateLifeRegen(this, ref num);

		if (lifeRegen <= -240 && num < 2)
			num = 2;

		// Extra patch context.
		lifeRegenCount += lifeRegen;
		while (lifeRegenCount >= 120) {
			lifeRegenCount -= 120;
			if (!immortal) {
				if (life < lifeMax)
					life++;

				if (life > lifeMax)
					life = lifeMax;
			}
		}

		if (num > 0) {
			while (lifeRegenCount <= -120 * num) {
				lifeRegenCount += 120 * num;
				GetHurtByDebuff(num);
			}
		}
		else {
			while (lifeRegenCount <= -120) {
				lifeRegenCount += 120;
				GetHurtByDebuff(1);
			}
		}
	}

	private void ApplyEelWhipDoT()
	{
		float num = 60f;
		int num2 = 0;
		int num3 = 3;
		int num4 = 50;
		int num5 = 50;
		if ((float)(++electricEelCounter) < num)
			return;

		electricEelCounter = 0;
		int num6 = 0;
		for (int i = 0; i < 255; i++) {
			Player player = Main.player[i];
			if (player.active && player.TagEffectState.Type == 5478 && player.TagEffectState.IsNPCTagged(whoAmI))
				num6++;
		}

		if (num6 == 0)
			return;

		int num7 = 600;
		if (!immortal) {
			for (int j = 0; j < Main.maxNPCs; j++) {
				if (num2 >= num3)
					break;

				if (j != whoAmI) {
					NPC nPC = Main.npc[j];
					if (nPC.active && nPC.markedByEelWhip && !nPC.immortal && (realLife == -1 || realLife != nPC.realLife) && !(Distance(nPC.Hitbox.ClosestPointInRect(base.Center)) > (float)num7)) {
						num2++;
						Vector2 vector = Main.rand.NextVector2FromRectangle(base.Hitbox);
						Vector2 vector2 = Main.rand.NextVector2FromRectangle(nPC.Hitbox);
						ParticleOrchestrator.RequestParticleSpawn(clientOnly: true, ParticleOrchestraType.BlueLightningSmallLong, new ParticleOrchestraSettings {
							PositionInWorld = vector,
							MovementVector = vector2 - vector
						});
					}
				}
			}
		}

		SoundEngine.PlaySound(HitSound, base.Center);
		if (Main.netMode != 1) {
			int num8 = (num4 + num2 * num5) * num6;
			GetHurtByDebuff(num8);
			if (Main.netMode == 2)
				NetMessage.TrySendData(153, -1, -1, null, whoAmI, num8);
		}
	}

	public void GetHurtByDebuff(int amount)
	{
		if (Main.netMode != 1)
			NPCDamageTracker.AddDamage(this, 255, amount);

		int num = whoAmI;
		if (realLife >= 0)
			num = realLife;

		if (!Main.npc[num].immortal)
			Main.npc[num].life -= amount;

		CombatText.NewText(new Rectangle((int)position.X, (int)position.Y, width, height), CombatText.LifeRegenNegative, amount, dramatic: false, dot: true);
		if (Main.npc[num].life > 0 || Main.npc[num].immortal)
			return;

		Main.npc[num].life = 1;
		if (Main.netMode != 1) {
			Main.npc[num].StrikeNPCNoInteraction(9999, 0f, 0);
			if (Main.netMode == 2)
				NetMessage.SendData(28, -1, -1, null, num, 9999f);
		}
	}

